  exp, shutdown, err := GetExporter(context.Background(), &tc.cfg)
  if err != nil { t.Fatal(err) }
  if exp == nil || shutdown == nil { t.Fatal("missing exporter or shutdown") }
  if err := shutdown(context.Background()); err != nil { t.Fatal(err) }
 }) }
}

func TestGetExporterRepeatedCalls(t *testing.T) {
 bad := config.TracingConfig{}
 if _, _, err := GetExporter(context.Background(), &bad); err == nil || !strings.HasPrefix(err.Error(), "unsupported tracing exporter:") { t.Fatalf("unexpected error: %v", err) }
 cfg := config.TracingConfig{Exporter: config.TracingJaeger, Jaeger: config.JaegerTracingConfig{Host: "localhost", Port: 6831}}
 first, shutdownFirst, err := GetExporter(context.Background(), &cfg)
 if err != nil { t.Fatal(err) }
 second, shutdownSecond, err := GetExporter(context.Background(), &cfg)
 if err != nil { t.Fatal(err) }
 if first == second { t.Fatal("calls shared an exporter") }
 if err := shutdownFirst(context.Background()); err != nil { t.Fatal(err) }
 if err := shutdownSecond(context.Background()); err != nil { t.Fatal(err) }
}

